-- Baseline schema, generated by Hibernate from the entities as they stood before Flyway was introduced.
-- Databases created earlier by ddl-auto=update already have it: Flyway baselines them at version 1 and skips this file.

    create table addresses (
        is_default boolean,
        created_at timestamp(6) with time zone not null,
        id bigint generated by default as identity,
        updated_at timestamp(6) with time zone not null,
        user_id bigint not null,
        postal_code varchar(20) not null,
        phone varchar(40),
        label varchar(60),
        country varchar(80) not null,
        city varchar(100) not null,
        region varchar(100),
        full_name varchar(120) not null,
        line1 varchar(200) not null,
        line2 varchar(200),
        primary key (id)
    );

    create table cart_items (
        quantity integer not null,
        cart_id bigint not null,
        created_at timestamp(6) with time zone not null,
        id bigint generated by default as identity,
        product_id bigint not null,
        updated_at timestamp(6) with time zone not null,
        personalisation_json varchar(4000),
        primary key (id)
    );

    create table carts (
        created_at timestamp(6) with time zone not null,
        id bigint generated by default as identity,
        updated_at timestamp(6) with time zone not null,
        user_id bigint unique,
        coupon_code varchar(40),
        token varchar(64) not null unique,
        primary key (id)
    );

    create table categories (
        featured boolean not null,
        sort_order integer not null,
        created_at timestamp(6) with time zone not null,
        id bigint generated by default as identity,
        updated_at timestamp(6) with time zone not null,
        name varchar(100) not null,
        slug varchar(120) not null unique,
        description varchar(600),
        image_url varchar(600),
        primary key (id)
    );

    create table coupons (
        active boolean not null,
        amount numeric(10,2) not null,
        min_order_total numeric(10,2),
        usage_limit integer,
        used_count integer not null,
        created_at timestamp(6) with time zone not null,
        expires_at timestamp(6) with time zone,
        id bigint generated by default as identity,
        updated_at timestamp(6) with time zone not null,
        type varchar(10) not null check (type in ('PERCENT','FIXED')),
        code varchar(40) not null unique,
        primary key (id)
    );

    create table enquiries (
        event_date date,
        quantity integer,
        created_at timestamp(6) with time zone not null,
        id bigint generated by default as identity,
        updated_at timestamp(6) with time zone not null,
        status varchar(20) not null check (status in ('NEW','IN_PROGRESS','QUOTED','CONFIRMED','CLOSED')),
        type varchar(20) not null check (type in ('CORPORATE','BULK','CUSTOM','CONTACT')),
        phone varchar(40),
        budget_range varchar(60),
        enquiry_topic varchar(80),
        event_type varchar(80),
        full_name varchar(120) not null,
        company_name varchar(160),
        email varchar(160) not null,
        personalisation_requirements varchar(1000),
        product_requirements varchar(1000),
        message varchar(3000),
        internal_notes varchar(6000),
        primary key (id)
    );

    create table faqs (
        active boolean not null,
        sort_order integer not null,
        created_at timestamp(6) with time zone not null,
        id bigint generated by default as identity,
        updated_at timestamp(6) with time zone not null,
        category varchar(80) not null,
        question varchar(300) not null,
        answer varchar(3000) not null,
        primary key (id)
    );

    create table newsletter_subscribers (
        active boolean not null,
        created_at timestamp(6) with time zone not null,
        id bigint generated by default as identity,
        updated_at timestamp(6) with time zone not null,
        email varchar(160) not null unique,
        primary key (id)
    );

    create table order_items (
        quantity integer not null,
        unit_price numeric(10,2) not null,
        created_at timestamp(6) with time zone not null,
        id bigint generated by default as identity,
        order_id bigint not null,
        product_id bigint,
        updated_at timestamp(6) with time zone not null,
        product_name varchar(160) not null,
        image_url varchar(600),
        personalisation_json varchar(4000),
        primary key (id)
    );

    create table orders (
        discount numeric(10,2) not null,
        shipping_fee numeric(10,2) not null,
        subtotal numeric(10,2) not null,
        total numeric(10,2) not null,
        created_at timestamp(6) with time zone not null,
        id bigint generated by default as identity,
        updated_at timestamp(6) with time zone not null,
        user_id bigint,
        payment_status varchar(20) not null check (payment_status in ('UNPAID','PENDING','PAID','REFUNDED','FAILED')),
        ship_postal_code varchar(20) not null,
        shipping_method varchar(20) not null check (shipping_method in ('STANDARD','EXPRESS','COLLECTION')),
        status varchar(20) not null check (status in ('PENDING','CONFIRMED','IN_PRODUCTION','SHIPPED','DELIVERED','CANCELLED')),
        order_number varchar(24) not null unique,
        coupon_code varchar(40),
        phone varchar(40),
        ship_phone varchar(40),
        carrier varchar(80),
        ship_country varchar(80) not null,
        ship_city varchar(100) not null,
        ship_region varchar(100),
        customer_name varchar(120) not null,
        ship_full_name varchar(120) not null,
        tracking_number varchar(120),
        email varchar(160) not null,
        ship_line1 varchar(200) not null,
        ship_line2 varchar(200),
        customer_notes varchar(1000),
        admin_notes varchar(4000),
        primary key (id)
    );

    create table payments (
        amount numeric(10,2) not null,
        created_at timestamp(6) with time zone not null,
        id bigint generated by default as identity,
        order_id bigint not null,
        updated_at timestamp(6) with time zone not null,
        status varchar(20) not null check (status in ('UNPAID','PENDING','PAID','REFUNDED','FAILED')),
        method varchar(40) not null,
        provider varchar(40) not null,
        provider_reference varchar(200),
        primary key (id)
    );

    create table product_categories (
        category_id bigint not null,
        product_id bigint not null,
        primary key (category_id, product_id)
    );

    create table product_images (
        sort_order integer not null,
        created_at timestamp(6) with time zone not null,
        id bigint generated by default as identity,
        product_id bigint not null,
        updated_at timestamp(6) with time zone not null,
        alt_text varchar(200),
        url varchar(600) not null,
        primary key (id)
    );

    create table product_personalisation (
        allow_date boolean not null,
        allow_event_details boolean not null,
        allow_initials boolean not null,
        allow_instructions boolean not null,
        allow_logo boolean not null,
        allow_message boolean not null,
        allow_name boolean not null,
        enabled boolean not null,
        extra_cost numeric(10,2),
        message_max_length integer not null,
        created_at timestamp(6) with time zone not null,
        id bigint generated by default as identity,
        product_id bigint not null unique,
        updated_at timestamp(6) with time zone not null,
        primary key (id)
    );

    create table products (
        active boolean not null,
        bestseller boolean not null,
        compare_at_price numeric(10,2),
        featured boolean not null,
        new_arrival boolean not null,
        price numeric(10,2) not null,
        sold_count integer not null,
        stock integer not null,
        created_at timestamp(6) with time zone not null,
        id bigint generated by default as identity,
        updated_at timestamp(6) with time zone not null,
        version bigint,
        name varchar(160) not null,
        slug varchar(180) not null unique,
        short_description varchar(300),
        specifications varchar(3000),
        description varchar(5000),
        primary key (id)
    );

    create table reviews (
        approved boolean not null,
        rating integer not null,
        created_at timestamp(6) with time zone not null,
        id bigint generated by default as identity,
        product_id bigint not null,
        updated_at timestamp(6) with time zone not null,
        user_id bigint not null,
        title varchar(140),
        body varchar(2000),
        primary key (id),
        unique (product_id, user_id)
    );

    create table roles (
        id bigint generated by default as identity,
        name varchar(40) not null unique,
        primary key (id)
    );

    create table site_content (
        created_at timestamp(6) with time zone not null,
        id bigint generated by default as identity,
        updated_at timestamp(6) with time zone not null,
        content_key varchar(80) not null unique,
        content_json varchar(20000) not null,
        primary key (id)
    );

    create table testimonials (
        active boolean not null,
        placeholder boolean not null,
        rating integer not null,
        sort_order integer not null,
        created_at timestamp(6) with time zone not null,
        id bigint generated by default as identity,
        updated_at timestamp(6) with time zone not null,
        author_name varchar(120) not null,
        occasion varchar(120),
        quote varchar(1200) not null,
        primary key (id)
    );

    create table user_roles (
        role_id bigint not null,
        user_id bigint not null,
        primary key (role_id, user_id)
    );

    create table users (
        email_verified boolean not null,
        enabled boolean not null,
        created_at timestamp(6) with time zone not null,
        id bigint generated by default as identity,
        reset_token_expires_at timestamp(6) with time zone,
        updated_at timestamp(6) with time zone not null,
        phone varchar(40),
        first_name varchar(80) not null,
        last_name varchar(80),
        reset_token varchar(100),
        verification_token varchar(100),
        email varchar(160) not null unique,
        password_hash varchar(255) not null,
        primary key (id)
    );

    create table wishlist_items (
        created_at timestamp(6) with time zone not null,
        id bigint generated by default as identity,
        product_id bigint not null,
        updated_at timestamp(6) with time zone not null,
        user_id bigint not null,
        primary key (id),
        unique (user_id, product_id)
    );

